var i=[{title:`Wie Fertigkeiten sich entwickeln`,text:`Am Anfang musst du über grundlegende Positionen und Abläufe nachdenken: wohin die Füße gehören, wie du die Hüften bewegst, wie du die Ellbogen führst. Mit Übung werden Bewegungen gleichmäßiger und brauchen weniger Aufmerksamkeit. Auf fortgeschrittenem Niveau kannst du die gelernte Bewegung an verschiedene Lasten und Situationen anpassen, was mehr verlangt, als eine perfekt aussehende Wiederholung auswendig zu lernen.`},{title:`Qualität der Übung`,text:`Häufige genaue Wiederholungen mit einer Last, die du kontrollieren kannst, bringen dir nützlicheres Lernen als gelegentliche chaotische Versuche mit vollem Einsatz. Beginne mit einer Version der Übung, die du kontrollieren kannst. Steigere über Bewegungsumfang, Widerstand, Gleichgewichtsanforderungen oder Tempo erst dann, wenn die aktuelle Version wiederholbar ist.`},{title:`Externe und interne Hinweise`,text:`Ein interner Hinweis könnte „spanne dein Gesäß an“ sein und ein externer Hinweis „drücke den Boden weg“. Unterschiedliche Hinweise funktionieren bei verschiedenen Menschen und Bewegungen. Nutze jeweils einen kurzen Hinweis, denn ein Dutzend Anweisungen zu Körperteilen in einer Wiederholung sind zu viel, um sie zu bewältigen.`},{title:`Rückmeldung`,text:`Ein Video aus einem hilfreichen Winkel kann ungleiche Tiefe, Gleichgewichtsprobleme oder unerwünschte Oberkörperbewegung zeigen, obwohl Kamerawinkel täuschen können. Ein Spiegel kann dir helfen, deine Position zu spüren, aber du musst ihn nicht ständig ansehen. Ein Coach lohnt sich bei ungewohnten komplexen Hebungen oder Technikproblemen, die immer wiederkehren.`},{title:`Ermüdung verändert das Lernen`,text:`Hohe Ermüdung kann die Präzision verringern, mache neue oder sehr anspruchsvolle Übungen deshalb nahe am Beginn des Trainings. Später in der Einheit passen vertraute und einfachere Übungen besser. Beende einen Satz, wenn deine Technik unkontrolliert wird, und betrachte nicht jeden Zusammenbruch als produktive Anstrengung.`},{title:`TrainUp nutzen`,text:`Jede Übungsseite unter „Übungen“ hat Fotos, Schritte und Technikhinweise, und der Plan wählt Übungen, die zu deinem Level und deiner Koordination passen. Erfasse die Wiederholungen, die du wirklich gemacht hast, und nutze die Trainingsnotizen, um aufzuschreiben, ob sie kontrolliert waren.`}];var r=[{label:`ACSM-Positionspapier 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`ACSM: Progressionsprinzipien`,url:`https://pubmed.ncbi.nlm.nih.gov/11828249/`}];var t={sections:i,sources:r};export{t as default,i as sections,r as sources};